#!/bin/bash
# อัปเดตเว็บ LinkPro: สมัคร + แนบ Resume → รอตรวจ → ส่งเอกสารที่หน้าตรวจสถานะ → นัดสัมภาษณ์
# วิธีใช้ (ในเซิร์ฟเวอร์): sudo bash update-linkpro.sh
set -eu
[ "$(id -u)" = 0 ] || { echo "กรุณารันด้วย sudo"; exit 1; }
APP=/opt/linkpro/app
BAK=/opt/linkpro/backup-$(date +%Y%m%d-%H%M%S)
TMP=$(mktemp -d)
echo '' | base64 -d | tar -xJ -C "$TMP"
NODE=$(grep '^ExecStart=' /etc/systemd/system/linkpro.service | sed 's/^ExecStart=//; s/ server.js$//')
"$NODE" --check "$TMP/server.js"
mkdir -p "$BAK" && cp -a "$APP/server.js" "$APP/public" "$BAK/"
cp -a "$TMP/." "$APP/"
chown -R linkpro:linkpro "$APP"
rm -rf "$TMP"
systemctl restart linkpro
sleep 2
if curl -fsS http://127.0.0.1:3100/api/public/jobs >/dev/null; then
  echo "เรียบร้อย อัปเดตแล้ว (สำรองไฟล์เดิมไว้ที่ $BAK)"
else
  echo "!! เว็บไม่ตอบ กำลังย้อนกลับเป็นเวอร์ชันเดิม"
  cp -a "$BAK/server.js" "$APP/server.js"; cp -a "$BAK/public/." "$APP/public/"; chown -R linkpro:linkpro "$APP"; systemctl restart linkpro
fi
